content.text:
Brief:
Un long cahier des charges pour un jeu de phare en plusieurs niveaux. Le joueur est le gardien d'un vieux phare sur une côte rocheuse, et chaque niveau se passe pendant une nuit de tempête. Des bateaux approchent depuis le large, et le joueur doit tourner le faisceau du phare en glissant le doigt autour de la tour pour éclairer chaque bateau avant qu'il ne touche les rochers. Un bateau éclairé assez longtemps trouve le chenal et rentre au port, ce qui compte pour l'objectif du niveau. Quand tous les bateaux d'une nuit sont rentrés, le niveau est gagné et une courte carte annonce la nuit suivante. Les nuits suivantes amènent plus de bateaux, du brouillard qui cache une partie de la mer et des vagues qui déplacent les bateaux. Si un bateau touche les rochers, la partie est perdue, avec un message qui dit quel bateau a coulé et un bouton pour rejouer la nuit. Je voudrais une mer bleu nuit, un faisceau jaune pâle et des bateaux rouges, dessinés simplement avec des formes plates. Le texte du jeu doit rester en français, avec le numéro de la nuit affiché en haut de l'écran pendant toute la partie.

Plan:
{"gameType":"stage-clear","input":"drag-follow","lang":"fr","loop":"Glissez le doigt autour de la tour pour tourner le faisceau et éclairer les bateaux avant qu'ils touchent les rochers. Faites rentrer tous les bateaux d'une nuit pour gagner la nuit; un bateau qui coule termine la partie.","slug":"le-gardien-du-phare","style":"paper-cut","title":"Le Gardien du Phare"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Gardien du Phare</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #f4ecd8;
11|     overflow: hidden;
12|     touch-action: none;
13|     font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
14|   }
15|   #wrap { position: fixed; inset: 0; }
16|   canvas { display: block; width: 100%; height: 100%; touch-action: none; }
17| </style>
18| </head>
19| <body>
20| <div id="wrap">
21| <canvas id="game"></canvas>
22| </div>
23| <script>
24| const CARTRIDGE = {
25|   send(type, payload = {}) {
26|     window.parent.postMessage(
27|       { source: "cartridge", v: 1, type, payload },
28|       "*",
29|     );
30|   },
31| };
32| </script>
33| <script>
34| (function(){
35|   const canvas = document.getElementById('game');
36|   const ctx = canvas.getContext('2d');
37|   let DPR = Math.max(1, window.devicePixelRatio || 1);
38|   let W = 0, H = 0;
39| 
40|   function resize(){
41|     W = window.innerWidth;
42|     H = window.innerHeight;
43|     DPR = Math.max(1, window.devicePixelRatio || 1);
44|     canvas.width = Math.round(W * DPR);
45|     canvas.height = Math.round(H * DPR);
46|     canvas.style.width = W + 'px';
47|     canvas.style.height = H + 'px';
48|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
49|   }
50|   window.addEventListener('resize', resize);
51|   resize();
52| 
53|   // ---------- palette ----------
54|   const COL_BG = '#f4ecd8';
55|   const COL_LAYER = '#e07a5f';
56|   const COL_ACCENT = '#3d405b';
57|   const COL_HILITE = '#81b29a';
58| 
59|   // ---------- seeded jitter helper ----------
60|   function mulberry32(a){
61|     return function(){
62|       a |= 0; a = a + 0x6D2B79F5 | 0;
63|       let t = Math.imul(a ^ a >>> 15, 1 | a);
64|       t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
65|       return ((t ^ t >>> 14) >>> 0) / 4294967296;
66|     };
67|   }
68|   const jitterRand = mulberry32(1337);
69|   function jitterPoint(x, y, seedOffset){
70|     const r1 = mulberry32(1337 + seedOffset * 2)();
71|     const r2 = mulberry32(1337 + seedOffset * 2 + 1)();
72|     return [x + (r1 - 0.5) * 3, y + (r2 - 0.5) * 3];
73|   }
74| 
75|   function paperPolygon(ctx, pts, fill, seedBase){
76|     ctx.save();
77|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
78|     ctx.shadowBlur = 6;
79|     ctx.shadowOffsetY = 3;
80|     ctx.beginPath();
81|     pts.forEach((p, i) => {
82|       const [jx, jy] = jitterPoint(p[0], p[1], seedBase + i);
83|       if (i === 0) ctx.moveTo(jx, jy);
84|       else ctx.lineTo(jx, jy);
85|     });
86|     ctx.closePath();
87|     ctx.fillStyle = fill;
88|     ctx.fill();
89|     ctx.restore();
90|   }
91| 
92|   function paperRoundRect(ctx, x, y, w, h, r, fill, seedBase){
93|     ctx.save();
94|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
95|     ctx.shadowBlur = 6;
96|     ctx.shadowOffsetY = 3;
97|     const [jx, jy] = jitterPoint(x, y, seedBase);
98|     ctx.beginPath();
99|     ctx.moveTo(jx + r, jy);
100|     ctx.arcTo(jx + w, jy, jx + w, jy + h, r);
101|     ctx.arcTo(jx + w, jy + h, jx, jy + h, r);
102|     ctx.arcTo(jx, jy + h, jx, jy, r);
103|     ctx.arcTo(jx, jy, jx + w, jy, r);
104|     ctx.closePath();
105|     ctx.fillStyle = fill;
106|     ctx.fill();
107|     ctx.restore();
108|   }
109| 
110|   function paperCircle(ctx, cx, cy, r, fill, seedBase){
111|     ctx.save();
112|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
113|     ctx.shadowBlur = 6;
114|     ctx.shadowOffsetY = 3;
115|     const [jx, jy] = jitterPoint(cx, cy, seedBase);
116|     ctx.beginPath();
117|     ctx.arc(jx, jy, r, 0, Math.PI * 2);
118|     ctx.fillStyle = fill;
119|     ctx.fill();
120|     ctx.restore();
121|   }
122| 
123|   // ---------- game state ----------
124|   const STATE = { TITLE: 'title', PLAYING: 'playing', STAGE_CLEAR: 'stage_clear', END: 'end' };
125|   let state = STATE.TITLE;
126|   let paused = false;
127| 
128|   let stage = 0;
129|   const STAGES = [
130|     { boats: 3, speed: 0.10, spawnGap: 3.2, goalText: "Sauvez 3 bateaux" },
131|     { boats: 4, speed: 0.13, spawnGap: 2.8, goalText: "Sauvez 4 bateaux" },
132|     { boats: 5, speed: 0.16, spawnGap: 2.4, goalText: "Sauvez 5 bateaux" },
133|     { boats: 6, speed: 0.19, spawnGap: 2.0, goalText: "Sauvez 6 bateaux" },
134|     { boats: 7, speed: 0.22, spawnGap: 1.8, goalText: "Sauvez 7 bateaux" },
135|   ];
136| 
137|   let score = 0;
138|   let beamAngle = 0; // radians
139|   let boats = [];
140|   let spawned = 0;
141|   let saved = 0;
142|   let spawnTimer = 0;
143|   let graceTimer = 0;
144|   let stageMsgTimer = 0;
145|   let endReason = null;
146|   let lastTime = null;
147|   let held = null; // pointer drag state
148|   let towerCenter = { x: 0, y: 0 };
149|   let towerRadius = 40;
150| 
151|   function toCanvas(evt){
152|     const rect = canvas.getBoundingClientRect();
153|     return {
154|       x: (evt.clientX - rect.left),
155|       y: (evt.clientY - rect.top)
156|     };
157|   }
158| 
159|   function backToTitle(){
160|     state = STATE.TITLE;
161|     paused = false;
162|     stage = 0;
163|     score = 0;
164|     boats = [];
165|     held = null;
166|   }
167| 
168|   function enterStage(next){
169|     stage = next;
170|     boats = [];
171|     spawned = 0;
172|     saved = 0;
173|     spawnTimer = 0;
174|     graceTimer = 2.5; // grace period
175|     stageMsgTimer = 2.5;
176|     state = STATE.PLAYING;
177|     CARTRIDGE.send("level", { index: stage });
178|   }
179| 
180|   function onGoalMet(){
181|     if (stage === STAGES.length){
182|       endReason = 'win';
183|       state = STATE.END;
184|       CARTRIDGE.send("end", { reason: "win", value: score });
185|     } else {
186|       state = STATE.STAGE_CLEAR;
187|       stageMsgTimer = 1.8;
188|     }
189|   }
190| 
191|   function onStageFailed(){
192|     endReason = 'lose';
193|     state = STATE.END;
194|     CARTRIDGE.send("end", { reason: "lose", value: score });
195|   }
196| 
197|   function startGame(){
198|     score = 0;
199|     CARTRIDGE.send("start");
200|     CARTRIDGE.send("score", { value: score });
201|     enterStage(1);
202|   }
203| 
204|   // ---------- boats ----------
205|   function spawnBoat(cfg){
206|     const angle = Math.random() * Math.PI * 2;
207|     const dist = Math.min(W, H) * 0.55;
208|     boats.push({
209|       angle: angle,
210|       dist: dist,
211|       speed: cfg.speed * (0.85 + Math.random() * 0.3),
212|       lit: false,
213|       wobble: Math.random() * Math.PI * 2,
214|       id: Math.random()
215|     });
216|   }
217| 
218|   function updateBoats(dt, cfg){
219|     for (let i = boats.length - 1; i >= 0; i--){
220|       const b = boats[i];
221|       b.wobble += dt * 2;
222|       // Check if lit by beam
223|       let diff = Math.abs(((b.angle - beamAngle + Math.PI * 3) % (Math.PI * 2)) - Math.PI);
224|       const beamHalfWidth = 0.28;
225|       b.lit = diff < beamHalfWidth;
226| 
227|       if (b.lit){
228|         // pushed back to safety, then removed (saved)
229|         b.dist += dt * 60;
230|         if (b.dist > Math.min(W, H) * 0.62){
231|           boats.splice(i, 1);
232|           saved++;
233|           score += 10;
234|           CARTRIDGE.send("score", { value: score });
235|           if (saved >= cfg.boats && spawned >= cfg.boats){
236|             onGoalMet();
237|             return;
238|           }
239|         }
240|       } else {
241|         b.dist -= b.speed * dt * 60;
242|         if (b.dist <= towerRadius + 18){
243|           onStageFailed();
244|           return;
245|         }
246|       }
247|     }
248|   }
249| 
250|   // ---------- input: rotate beam by dragging around tower ----------
251|   canvas.addEventListener('pointerdown', (event) => {
252|     if (state === STATE.TITLE){
253|       startGame();
254|       return;
255|     }
256|     if (state === STATE.END){
257|       backToTitle();
258|       return;
259|     }
260|     if (state !== STATE.PLAYING) return;
261|     const p = toCanvas(event);
262|     held = { pointerId: event.pointerId };
263|     canvas.setPointerCapture(event.pointerId);
264|     updateBeamFromPoint(p);
265|   });
266|   canvas.addEventListener('pointermove', (event) => {
267|     if (!held) return;
268|     const p = toCanvas(event);
269|     updateBeamFromPoint(p);
270|   });
271|   function endHold(){ held = null; }
272|   canvas.addEventListener('pointerup', endHold);
273|   canvas.addEventListener('pointercancel', endHold);
274| 
275|   function updateBeamFromPoint(p){
276|     const dx = p.x - towerCenter.x;
277|     const dy = p.y - towerCenter.y;
278|     beamAngle = Math.atan2(dy, dx);
279|   }
280| 
281|   // ---------- host messages ----------
282|   window.addEventListener("message", (event) => {
283|     const data = event.data;
284|     if (!data || data.source !== "cartridge-host") return;
285|     if (data.type === "pause") paused = true;
286|     if (data.type === "resume") paused = false;
287|     if (data.type === "reset") backToTitle();
288|   });
289| 
290|   // ---------- drawing ----------
291|   function drawBackground(){
292|     ctx.fillStyle = COL_BG;
293|     ctx.fillRect(0, 0, W, H);
294|     // sea layer (rocks ring)
295|     const cx = towerCenter.x, cy = towerCenter.y;
296|     const seaR = Math.min(W, H) * 0.62;
297|     paperCircle(ctx, cx, cy, seaR, '#cfe3da', 500);
298|     // rocks ring near tower
299|     const rockR = towerRadius + 14;
300|     ctx.save();
301|     for (let i = 0; i < 14; i++){
302|       const a = (i / 14) * Math.PI * 2;
303|       const rx = cx + Math.cos(a) * rockR;
304|       const ry = cy + Math.sin(a) * rockR;
305|       paperCircle(ctx, rx, ry, 7, COL_ACCENT, 600 + i);
306|     }
307|     ctx.restore();
308|   }
309| 
310|   function drawBeam(){
311|     const cx = towerCenter.x, cy = towerCenter.y;
312|     const len = Math.min(W, H) * 0.62;
313|     const halfWidth = 0.28;
314|     ctx.save();
315|     ctx.globalAlpha = 0.35;
316|     ctx.beginPath();
317|     ctx.moveTo(cx, cy);
318|     ctx.arc(cx, cy, len, beamAngle - halfWidth, beamAngle + halfWidth);
319|     ctx.closePath();
320|     ctx.fillStyle = COL_HILITE;
321|     ctx.fill();
322|     ctx.restore();
323|   }
324| 
325|   function drawTower(){
326|     const cx = towerCenter.x, cy = towerCenter.y;
327|     // base
328|     paperRoundRect(ctx, cx - towerRadius, cy - towerRadius, towerRadius * 2, towerRadius * 2, 12, COL_LAYER, 10);
329|     // stripes
330|     paperRoundRect(ctx, cx - towerRadius * 0.6, cy - towerRadius * 0.9, towerRadius * 1.2, towerRadius * 0.4, 6, COL_ACCENT, 20);
331|     // lamp room
332|     paperCircle(ctx, cx, cy, towerRadius * 0.42, COL_HILITE, 30);
333|     // small light dot pointing beam direction
334|     const lx = cx + Math.cos(beamAngle) * towerRadius * 0.6;
335|     const ly = cy + Math.sin(beamAngle) * towerRadius * 0.6;
336|     paperCircle(ctx, lx, ly, 6, COL_ACCENT, 40);
337|   }
338| 
339|   function drawBoat(b){
340|     const cx = towerCenter.x + Math.cos(b.angle) * b.dist;
341|     const cy = towerCenter.y + Math.sin(b.angle) * b.dist;
342|     const wob = Math.sin(b.wobble) * 3;
343|     const col = b.lit ? COL_HILITE : COL_LAYER;
344|     ctx.save();
345|     ctx.translate(cx, cy + wob);
346|     const hullPts = [
347|       [-16, 6], [16, 6], [11, 14], [-11, 14]
348|     ];
349|     paperPolygon(ctx, hullPts, col, Math.floor(b.id * 1000));
350|     // sail
351|     const sailPts = [
352|       [0, 6], [0, -20], [13, 5]
353|     ];
354|     paperPolygon(ctx, sailPts, COL_ACCENT, Math.floor(b.id * 1000) + 5);
355|     ctx.restore();
356|   }
357| 
358|   function drawTitle(){
359|     drawBackground();
360|     drawTower();
361|     // title card
362|     const cardW = Math.min(W * 0.86, 480);
363|     const cardH = 260;
364|     const cx = W / 2 - cardW / 2;
365|     const cy = H / 2 - cardH / 2;
366|     paperRoundRect(ctx, cx, cy, cardW, cardH, 18, '#fffaf0', 900);
367|     ctx.fillStyle = COL_ACCENT;
368|     ctx.textAlign = 'center';
369|     ctx.font = 'bold 30px sans-serif';
370|     ctx.fillText('Le Gardien du Phare', W / 2, cy + 60);
371|     ctx.font = '16px sans-serif';
372|     wrapText(ctx, "Glissez autour de la tour pour tourner le faisceau et sauver les bateaux des rochers.", W / 2, cy + 100, cardW - 60, 22);
373|     ctx.font = 'bold 20px sans-serif';
374|     ctx.fillStyle = COL_LAYER;
375|     ctx.fillText('Touchez pour commencer', W / 2, cy + cardH - 40);
376|   }
377| 
378|   function wrapText(ctx, text, x, y, maxWidth, lineHeight){
379|     const words = text.split(' ');
380|     let line = '';
381|     let yy = y;
382|     for (let n = 0; n < words.length; n++){
383|       const testLine = line + words[n] + ' ';
384|       const metrics = ctx.measureText(testLine);
385|       if (metrics.width > maxWidth && n > 0){
386|         ctx.fillText(line, x, yy);
387|         line = words[n] + ' ';
388|         yy += lineHeight;
389|       } else {
390|         line = testLine;
391|       }
392|     }
393|     ctx.fillText(line, x, yy);
394|   }
395| 
396|   function drawHUD(){
397|     // score plate
398|     paperRoundRect(ctx, 12, 12, 150, 44, 10, '#fffaf0', 950);
399|     ctx.fillStyle = COL_ACCENT;
400|     ctx.textAlign = 'left';
401|     ctx.font = 'bold 18px sans-serif';
402|     ctx.fillText('Score: ' + score, 24, 40);
403| 
404|     // stage plate
405|     const cfg = STAGES[stage - 1];
406|     if (cfg){
407|       const plateW = Math.min(W * 0.7, 320);
408|       paperRoundRect(ctx, W / 2 - plateW / 2, 12, plateW, 44, 10, '#fffaf0', 960);
409|       ctx.fillStyle = COL_ACCENT;
410|       ctx.textAlign = 'center';
411|       ctx.font = 'bold 16px sans-serif';
412|       ctx.fillText('Étape ' + stage + ': ' + saved + '/' + cfg.boats + ' sauvés', W / 2, 40);
413|     }
414| 
415|     if (stageMsgTimer > 0 && cfg){
416|       const cardW = Math.min(W * 0.8, 420);
417|       const cardH = 90;
418|       const cx = W / 2 - cardW / 2;
419|       const cy = H * 0.28;
420|       paperRoundRect(ctx, cx, cy, cardW, cardH, 16, '#fffaf0', 970);
421|       ctx.fillStyle = COL_ACCENT;
422|       ctx.textAlign = 'center';
423|       ctx.font = 'bold 22px sans-serif';
424|       ctx.fillText('Étape ' + stage, W / 2, cy + 35);
425|       ctx.font = '16px sans-serif';
426|       ctx.fillText(cfg.goalText, W / 2, cy + 65);
427|     }
428|   }
429| 
430|   function drawStageClearOverlay(){
431|     const cardW = Math.min(W * 0.8, 420);
432|     const cardH = 140;
433|     const cx = W / 2 - cardW / 2;
434|     const cy = H / 2 - cardH / 2;
435|     paperRoundRect(ctx, cx, cy, cardW, cardH, 16, '#fffaf0', 980);
436|     ctx.fillStyle = COL_ACCENT;
437|     ctx.textAlign = 'center';
438|     ctx.font = 'bold 26px sans-serif';
439|     ctx.fillText('Étape ' + stage + ' réussie !', W / 2, cy + 55);
440|     ctx.font = '16px sans-serif';
441|     ctx.fillText('Préparez-vous pour la suite...', W / 2, cy + 90);
442|   }
443| 
444|   function drawEndOverlay(){
445|     const cardW = Math.min(W * 0.8, 440);
446|     const cardH = 200;
447|     const cx = W / 2 - cardW / 2;
448|     const cy = H / 2 - cardH / 2;
449|     paperRoundRect(ctx, cx, cy, cardW, cardH, 18, '#fffaf0', 990);
450|     ctx.fillStyle = COL_ACCENT;
451|     ctx.textAlign = 'center';
452|     ctx.font = 'bold 28px sans-serif';
453|     if (endReason === 'win'){
454|       ctx.fillText('Toutes les nuits sont sauvées !', W / 2, cy + 60);
455|     } else {
456|       ctx.fillText('Un bateau a coulé...', W / 2, cy + 60);
457|     }
458|     ctx.font = '18px sans-serif';
459|     ctx.fillText('Score final: ' + score, W / 2, cy + 100);
460|     ctx.font = 'bold 18px sans-serif';
461|     ctx.fillStyle = COL_LAYER;
462|     ctx.fillText('Touchez pour recommencer', W / 2, cy + cardH - 30);
463|   }
464| 
465|   // ---------- main loop ----------
466|   function step(ts){
467|     requestAnimationFrame(step);
468|     if (lastTime === null) lastTime = ts;
469|     let dt = (ts - lastTime) / 1000;
470|     lastTime = ts;
471|     if (dt > 0.05) dt = 0.05;
472| 
473|     towerCenter.x = W / 2;
474|     towerCenter.y = H / 2;
475|     towerRadius = Math.max(36, Math.min(W, H) * 0.07);
476| 
477|     if (paused){
478|       render();
479|       return;
480|     }
481| 
482|     if (state === STATE.PLAYING){
483|       const cfg = STAGES[stage - 1];
484|       if (graceTimer > 0) graceTimer -= dt;
485|       if (stageMsgTimer > 0) stageMsgTimer -= dt;
486| 
487|       spawnTimer -= dt;
488|       if (graceTimer <= 0 && spawnTimer <= 0 && spawned < cfg.boats){
489|         spawnBoat(cfg);
490|         spawned++;
491|         spawnTimer = cfg.spawnGap;
492|       }
493|       if (graceTimer <= 0){
494|         updateBoats(dt, cfg);
495|       } else {
496|         // still allow gentle wobble during grace
497|         boats.forEach(b => b.wobble += dt * 2);
498|       }
499|     } else if (state === STATE.STAGE_CLEAR){
500|       stageMsgTimer -= dt;
501|       if (stageMsgTimer <= 0){
502|         enterStage(stage + 1);
503|       }
504|     }
505| 
506|     render();
507|   }
508| 
509|   function render(){
510|     ctx.clearRect(0, 0, W, H);
511|     if (state === STATE.TITLE){
512|       drawTitle();
513|     } else if (state === STATE.PLAYING){
514|       drawBackground();
515|       drawBeam();
516|       boats.forEach(drawBoat);
517|       drawTower();
518|       drawHUD();
519|     } else if (state === STATE.STAGE_CLEAR){
520|       drawBackground();
521|       boats.forEach(drawBoat);
522|       drawTower();
523|       drawHUD();
524|       drawStageClearOverlay();
525|     } else if (state === STATE.END){
526|       drawBackground();
527|       boats.forEach(drawBoat);
528|       drawTower();
529|       drawHUD();
530|       drawEndOverlay();
531|     }
532|     if (paused){
533|       ctx.save();
534|       ctx.fillStyle = 'rgba(61,64,91,0.5)';
535|       ctx.fillRect(0, 0, W, H);
536|       ctx.fillStyle = '#fffaf0';
537|       ctx.textAlign = 'center';
538|       ctx.font = 'bold 28px sans-serif';
539|       ctx.fillText('Pause', W / 2, H / 2);
540|       ctx.restore();
541|     }
542|   }
543| 
544|   // ---------- boot ----------
545|   towerCenter.x = W / 2;
546|   towerCenter.y = H / 2;
547|   requestAnimationFrame((ts) => {
548|     lastTime = ts;
549|     render();
550|     CARTRIDGE.send("boot", { title: "Le Gardien du Phare", gameType: "stage-clear", lang: "fr" });
551|     requestAnimationFrame(step);
552|   });
553| })();
554| </script>
555| </body>
556| </html>
557|

